    // Block 2 Scene 1
    "b2.s1.title": "Where the journey begins",
    "b2.s1.intro": "👉 In the dark, it's easy to take a wrong turn 🙂\nLight helps keep the right direction.\n\nLet's figure out how everything works.",
    "b2.s1.point1.title": "👉 How everything works here",
    "b2.s1.point1.desc": "• what the rules are\n• how accounting tracks your results",
    "b2.s1.point2.title": "👉 Ways to earn here",
    "b2.s1.point2.desc": "• how to earn more by combining different approaches",
    "b2.s1.point3.title": "👉 How to act without extra steps",
    "b2.s1.point3.desc": "• how to reach your desired result faster",
    "b2.s1.dandy": "When you understand the rules — moving forward becomes much easier 🙂",

    "b2.s2.title": "Reporting periods",
    "b2.s2.period1": "1st–14th",
    "b2.s2.period2": "15th–end of month",
    "b2.s2.explain": "• sales volume is recorded during these periods\n• results are summarized\n• bonuses are calculated",
    "b2.s2.payouts.title": "When do accruals and payouts happen",
    "b2.s2.payouts.desc": "• accruals for the previous reporting period happen on the <b>1st and 15th at 2:00 AM</b> Astana time\n• you can order payouts for the previous period only on the <b>1st and 15th</b>, and also on the <b>2nd and 16th until 17:30</b> Astana time\n• to receive payouts, you need to submit a withdrawal request and provide documents",
    "b2.s2.dandy": "It's like summarizing the month 🙂\nFirst we count results — then payouts.",

    "b2.s3.title": "What is PV",
    "b2.s3.explain": "PV — a unit for tracking sales volume.\n\nIt's used so accounting can accurately calculate work results.",
    "b2.s3.important.title": "Important:",
    "b2.s3.important.desc": "• PV is not money\n• PV shows sales volume\n• bonuses are calculated from PV",
    "b2.s3.examples.title": "Examples:",
    "b2.s3.example1": "1 product pack = 60 PV",
    "b2.s3.example2": "cream = 120 PV",
    "b2.s3.analogy": "PV is like kilometers on a speedometer.\nThey show the distance.\nMoney is the result of the journey.",
    "b2.s3.bottom": "PV shows volume.\nMoney is the result of that volume.",

    "b2.s4.title": "How PV turns into money",
    "b2.s4.step1": "✔ first, total PV volume is calculated",
    "b2.s4.step2": "✔ then the marketing plan determines which part of PV participates in payouts",
    "b2.s4.step3": "✔ money is calculated from those PV",
    "b2.s4.note": "Not all volume turns into payouts.\nPayouts are calculated according to marketing plan rules.",
    "b2.s4.conversion.title": "For reference, when calculating payouts, 1 PV equals:",
    "b2.s4.conv.rub": "100 rubles",
    "b2.s4.conv.kzt": "500 tenge",
    "b2.s4.conv.uzs": "12,000 sum",
    "b2.s4.conv.usd": "1 US dollar",
    "b2.s4.dandy": "PV is the result of work 🙂\nAnd payouts are the result of proper calculation.",

